(()=>{'use strict';const A=window.omniAddon,T=window.OBAddonTools;if(!A||!T||!A.top)return;let ui,timer=0,changed=new Map(),videos=new Map(),ended=false;function mark(e,prop,value){if(!e)return;const key=prop;if(!changed.has(e))changed.set(e,new Map());const m=changed.get(e);if(!m.has(key))m.set(key,{before:e.getAttribute(key),applied:value});e.setAttribute(key,value)}function reset(){for(const [e,props] of changed)for(const [key,row] of props)if(e.getAttribute(key)===row.applied){if(row.before===null)e.removeAttribute(key);else e.setAttribute(key,row.before)}changed.clear();for(const [v,row] of videos){v.removeEventListener('ended',row.end);v.removeEventListener('play',row.play);if(v.playbackRate===row.applied)v.playbackRate=row.before;if(row.autoplay)v.autoplay=true}videos.clear()}function apply(){if(!A.active)return;const s=A.settings.all();for(const v of document.querySelectorAll('video')){let row=videos.get(v);if(!row){row={before:v.playbackRate,applied:Number(s.speed),autoplay:v.autoplay,end:()=>{ended=true},play:()=>{if(ended&&A.settings.get('stopAutoplay')){v.pause();ui.status.textContent='Autoplay stopped. Press Play to continue.';ended=false}}};videos.set(v,row);v.addEventListener('ended',row.end);v.addEventListener('play',row.play)}row.applied=Number(s.speed);if(v.playbackRate!==row.applied)v.playbackRate=row.applied;if(s.stopAutoplay)v.autoplay=false}if(s.shorts)for(const e of document.querySelectorAll('ytd-reel-shelf-renderer,ytd-rich-shelf-renderer[is-shorts],a[href^="/shorts/"]'))mark(e,'hidden','');if(s.comments)for(const e of document.querySelectorAll('ytd-comments,#comments'))mark(e,'hidden','');if(s.theatre)mark(document.querySelector('ytd-watch-flexy'),'theater','');if(s.largeControls)for(const e of document.querySelectorAll('.ytp-chrome-controls'))if(!e.classList.contains('ob-yt-comfort-large'))mark(e,'class',e.className+' ob-yt-comfort-large');if(ui)ui.element.querySelector('button').hidden=!s.fullscreen}function start(){ui=T.panel(A.id,'YouTube comfort','https://www.youtube.com/','Original Omni controls');ui.button('Enter fullscreen',()=>{const v=document.querySelector('video');if(!v?.requestFullscreen){ui.status.textContent='Fullscreen requires native support.';return}v.requestFullscreen().catch(()=>ui.status.textContent='Use Omni’s fullscreen control.');});ui.status.textContent='Quality and codec preferences await native integration.';apply();timer=setInterval(apply,1000)}function stop(){clearInterval(timer);reset();ui?.element.remove();ui=null;ended=false}A.onDisable(stop);A.onEnable(start);A.onSettings(()=>{if(A.active){reset();apply()}});start()})();